// Export helpers: SVG, PNG and a redacted JSON summary.
//
// The SVG is generated from the model rather than scraped from the DOM, so it
// contains every row (not just the virtualized ones) and needs no external
// fonts — it opens correctly in any viewer, offline.

import { formatDuration } from './stats.js';
import { axisTicks } from './render/waterfall.js';

const ROW = 18;
const LABEL_W = 340;
const BAR_W = 760;
const PAD = 16;
const HEADER = 74;

export function buildSvg(ctx) {
  const { rows, colors, view, cp, showCritical, trace, title } = ctx;
  const width = LABEL_W + BAR_W + PAD * 2;
  const height = HEADER + rows.length * ROW + PAD;
  const span = view.end - view.start || 1;
  const x = (t) => LABEL_W + PAD + ((t - view.start) / span) * BAR_W;

  const parts = [];
  parts.push(
    `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" ` +
      `viewBox="0 0 ${width} ${height}" font-family="ui-monospace, SFMono-Regular, Menlo, Consolas, monospace">`,
  );
  parts.push(`<rect width="${width}" height="${height}" fill="#ffffff"/>`);
  parts.push(
    `<text x="${PAD}" y="26" font-size="14" font-weight="600" fill="#16181d">${esc(title)}</text>`,
  );
  parts.push(
    `<text x="${PAD}" y="44" font-size="11" fill="#5b6270">${esc(
      `${rows.length} rows · ${trace.spans.length} spans · ${trace.services.length} services · ` +
        `${formatDuration(trace.duration)} total`,
    )}</text>`,
  );

  for (const tick of axisTicks(view, 8)) {
    const tx = LABEL_W + PAD + (tick.pct / 100) * BAR_W;
    parts.push(
      `<line x1="${round(tx)}" y1="${HEADER - 12}" x2="${round(tx)}" y2="${height - PAD}" stroke="#e4e6ea"/>`,
    );
    parts.push(
      `<text x="${round(tx) + 3}" y="${HEADER - 16}" font-size="10" fill="#7b8393">${esc(
        formatDuration(tick.value),
      )}</text>`,
    );
  }

  rows.forEach((s, i) => {
    const y = HEADER + i * ROW;
    if (i % 2 === 1) {
      parts.push(`<rect x="0" y="${y}" width="${width}" height="${ROW}" fill="#fafbfc"/>`);
    }
    const indent = PAD + s.depth * 10;
    const label = truncate(s.name, Math.max(4, Math.floor((LABEL_W - indent - 90) / 6.1)));
    parts.push(
      `<circle cx="${indent + 4}" cy="${y + ROW / 2}" r="3.2" fill="${esc(colors.get(s.service))}"/>`,
    );
    parts.push(
      `<text x="${indent + 12}" y="${y + 12.5}" font-size="10.5" fill="${
        s.statusCode === 'error' ? '#c62828' : '#16181d'
      }">${esc(label)}</text>`,
    );
    parts.push(
      `<text x="${LABEL_W + PAD - 6}" y="${y + 12.5}" font-size="9.5" text-anchor="end" fill="#8b93a1">${esc(
        truncate(s.service, 16),
      )}</text>`,
    );

    const bx = x(s.start);
    const bw = Math.max((s.duration / span) * BAR_W, 1);
    const cx0 = Math.max(bx, LABEL_W + PAD);
    const cx1 = Math.min(bx + bw, LABEL_W + PAD + BAR_W);
    if (cx1 > cx0) {
      const faded = showCritical && !cp.uids.has(s.uid);
      parts.push(
        `<rect x="${round(cx0)}" y="${y + 4}" width="${round(cx1 - cx0)}" height="${ROW - 8}" rx="2" ` +
          `fill="${esc(colors.get(s.service))}" opacity="${faded ? 0.3 : 0.9}"/>`,
      );
      if (s.statusCode === 'error') {
        parts.push(
          `<rect x="${round(cx0)}" y="${y + 4}" width="${round(cx1 - cx0)}" height="${ROW - 8}" rx="2" ` +
            'fill="none" stroke="#c62828" stroke-width="1.2"/>',
        );
      }
      parts.push(
        `<text x="${round(Math.min(cx1 + 4, width - PAD))}" y="${y + 12.5}" font-size="9.5" fill="#5b6270"${
          cx1 + 60 > width - PAD ? ' text-anchor="end"' : ''
        }>${esc(formatDuration(s.duration))}</text>`,
      );
    }
  });

  if (showCritical) {
    const rowIndex = new Map(rows.map((r, i) => [r.uid, i]));
    for (const seg of cp.segments) {
      const row = rowIndex.get(seg.uid);
      if (row === undefined) continue;
      const y = HEADER + row * ROW;
      const sx = Math.max(x(seg.start), LABEL_W + PAD);
      const ex = Math.min(x(seg.end), LABEL_W + PAD + BAR_W);
      if (ex > sx) {
        parts.push(
          `<rect x="${round(sx)}" y="${y + ROW - 5}" width="${round(ex - sx)}" height="2.5" fill="#111827"/>`,
        );
      }
    }
  }

  parts.push(
    `<text x="${PAD}" y="${height - 4}" font-size="9" fill="#9aa1ae">` +
      'Generated by trace-waterfall-viewer</text>',
  );
  parts.push('</svg>');
  return parts.join('\n');
}

function round(n) {
  return Math.round(n * 100) / 100;
}

function truncate(text, max) {
  const s = String(text);
  return s.length <= max ? s : `${s.slice(0, Math.max(1, max - 1))}…`;
}

export function esc(text) {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

/** Rasterise an SVG string through a canvas. No network access involved. */
export function svgToPngBlob(svg, scale = 2) {
  return new Promise((resolve, reject) => {
    const url = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
    const image = new Image();
    image.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = Math.round(image.width * scale);
      canvas.height = Math.round(image.height * scale);
      const ctx = canvas.getContext('2d');
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.setTransform(scale, 0, 0, scale, 0, 0);
      ctx.drawImage(image, 0, 0);
      canvas.toBlob((blob) => (blob ? resolve(blob) : reject(new Error('canvas.toBlob failed'))), 'image/png');
    };
    image.onerror = () => reject(new Error('Could not rasterise the SVG'));
    image.src = url;
  });
}

/**
 * A shareable, deliberately reduced view of the trace: structure and timings
 * only. Attributes, events, resource data and raw payloads are dropped, since
 * those are where customer identifiers and query text live.
 */
export function shareableSubset(trace, cp) {
  return {
    generator: 'trace-waterfall-viewer',
    note: 'Structure and timings only. Attributes, events and raw payloads were removed.',
    traceIds: trace.traceIds,
    durationNs: trace.duration,
    spanCount: trace.spans.length,
    services: trace.services,
    criticalPathNs: cp.total,
    spans: trace.order.map((s) => ({
      id: s.uid,
      parent: s.parentUid,
      name: s.name,
      service: s.service,
      kind: s.kind,
      depth: s.depth,
      startNs: s.start,
      durationNs: s.duration,
      selfTimeNs: s.selfTime,
      status: s.statusCode,
      orphaned: s.orphaned || undefined,
      criticalPathNs: cp.byUid.get(s.uid) || undefined,
    })),
  };
}

export function download(filename, blob) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 5000);
}

/** Clipboard with a synchronous fallback for `file://` and older browsers. */
export async function copyText(text) {
  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text);
      return true;
    }
  } catch {
    /* fall through to the textarea path */
  }
  const ta = document.createElement('textarea');
  ta.value = text;
  ta.setAttribute('readonly', '');
  ta.style.position = 'fixed';
  ta.style.opacity = '0';
  document.body.appendChild(ta);
  ta.select();
  let ok = false;
  try {
    ok = document.execCommand('copy');
  } catch {
    ok = false;
  }
  ta.remove();
  return ok;
}
